import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { SoftwarePackageService } from '../../services/software-package.service';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-view-software-package',
  templateUrl: './view-software-package.component.html',
  styleUrls: ['./view-software-package.component.css']
})
export class ViewSoftwarePackageComponent implements OnInit {
  package: SoftwarePackage | null = null;
  loading = false;
  error: string | null = null;
  deleting = false;
  currentImage = '';

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private softwarePackageService: SoftwarePackageService,
    public auth: AuthService
  ) {}

  ngOnInit(): void {
    this.auth.restoreSession();
    this.fetchPackage();
  }

  get isAdmin(): boolean {
    return this.auth.isAdmin;
  }

  async fetchPackage(): Promise<void> {
    this.loading = true;
    this.error = null;
    try {
      const id = Number(this.route.snapshot.paramMap.get('id'));
      const data = await this.softwarePackageService.fetchPackageById(id);
      if (data) {
        this.package = data;
        this.currentImage = data.thumbnail || (data.images && data.images[0]) || 'https://via.placeholder.com/600';
      } else {
        this.error = 'Software package not found';
      }
    } catch (err) {
      this.error = 'Failed to load package';
      console.error(err);
    } finally {
      this.loading = false;
    }
  }

  async handleDelete(): Promise<void> {
    if (!confirm('Are you sure you want to delete this software package?')) {
      return;
    }

    this.deleting = true;
    const id = this.package!.id;
    const success = await this.softwarePackageService.deletePackage(id);
    this.deleting = false;

    if (success) {
      this.router.navigate(['/packages']);
    } else {
      alert('Failed to delete software package');
    }
  }

  goBack(): void {
    this.router.navigate(['/packages']);
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="page-header">
    <div class="header-content">
      <button (click)="goBack()" class="inline-flex items-center text-sm text-gray-600 hover:text-primary">
        <svg class="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Back to Packages
      </button>
      <span class="text-sm font-medium text-gray-500">Package Details</span>
    </div>
  </header>

  <div class="page-container">
    <div *ngIf="loading" class="flex justify-center py-16">
      <div class="inline-block animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
    </div>

    <div *ngIf="!loading && error" class="text-center py-16">
      <div class="text-red-500 mb-3">
        <svg class="w-6 h-6 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-sm text-red-600">{{ error }}</p>
    </div>

    <div *ngIf="!loading && !error && package" class="card-base">
      <div class="grid grid-cols-1 lg:grid-cols-12 gap-0">
        <div class="lg:col-span-6 relative bg-gray-100 aspect-[4/5] lg:aspect-[1/1] overflow-hidden">
          <img [src]="currentImage" [alt]="package.title" class="w-full h-full object-cover" />
          <div class="absolute top-4 left-4 bg-white bg-opacity-90 px-3 py-1 rounded-full shadow-sm">
            <span class="text-xs font-medium text-gray-700">{{ package.category }}</span>
          </div>
        </div>

        <div class="lg:col-span-6 p-6 lg:p-8 flex flex-col">
          <div class="flex items-start justify-between mb-3">
            <div>
              <span class="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1 block">{{ package.brand }}</span>
              <h1 class="text-xl font-bold text-gray-900 mb-1">{{ package.title }}</h1>
              <div class="flex items-center gap-1.5 mb-3">
                <svg class="w-4 h-4 text-yellow-400" fill="currentColor" viewBox="0 0 20 20">
                  <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                </svg>
                <span class="text-sm font-medium text-gray-700">{{ package.rating || 'N/A' }}</span>
              </div>
            </div>
          </div>

          <p class="text-gray-600 mb-6 leading-relaxed text-sm">{{ package.description }}</p>

          <div class="space-y-4 mb-8">
            <div class="flex items-center justify-between py-3 border-b border-gray-100 last:border-0">
              <span class="text-sm text-gray-600">Available Licenses</span>
              <span class="text-sm font-medium text-gray-900" [class.text-green-600]="package.stock > 0" [class.text-red-600]="package.stock <= 0">
                {{ package.stock > 0 ? package.stock + ' left' : 'Out of stock' }}
              </span>
            </div>
            <div *ngIf="package.sku" class="flex items-center justify-between py-3 border-b border-gray-100 last:border-0">
              <span class="text-sm text-gray-600">SKU</span>
              <span class="text-sm font-medium text-gray-900 font-mono">{{ package.sku }}</span>
            </div>
          </div>

          <div *ngIf="isAdmin" class="pt-4 border-t border-gray-100">
            <button (click)="handleDelete()" [disabled]="deleting" class="w-full bg-red-600 text-white py-2.5 rounded-lg text-sm font-medium hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2">
              <svg *ngIf="!deleting" class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
              <span *ngIf="deleting">Deleting...</span>
              <span *ngIf="!deleting">Delete Package</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
